tool.command:
python3 -c "
import anndata as ad
import sys
import argparse

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--input', required=True)
    parser.add_argument('--output', required=True)
    parser.add_argument('--operation', required=True)
    args = parser.parse_args()

    adata = ad.read(args.input)

    if args.operation == 'concatenate':
        adata.concatenate(adata)
    elif args.operation == 'obs_names_make_unique':
        adata.obs_names_make_unique()
    elif args.operation == 'var_names_make_unique':
        adata.var_names_make_unique()
    elif args.operation == 'rename_categories':
        adata.rename_categories('obs', {'old': 'new'})
    elif args.operation == 'remove_keys':
        adata.obs.drop(['key'], axis=1, inplace=True)
    elif args.operation == 'flag_genes':
        adata.var['mito'] = adata.var_names.str.startswith('MT-')
    elif args.operation == 'strings_to_categoricals':
        adata.strings_to_categoricals()
    elif args.operation == 'transpose':
        adata.transpose()
    elif args.operation == 'add_annotation':
        adata.obs['new_annotation'] = 'value'
    elif args.operation == 'split':
        adata.split('obs_key')
    elif args.operation == 'filter':
        adata = adata[adata.obs['key'] == 'value']
    elif args.operation == 'freeze_raw':
        adata.raw = adata

    adata.write_loom(args.output)

if __name__ == '__main__':
    main()
" $*
